# Adaptive rejection sampling for log-concave densities.
# The density function is evaluated on a vector and must return a vector of
# non-negative, finite density values (zero is permitted away from knots).

sample_count <- 1L

.ars_stop <- function(message) {
  stop(message, call. = FALSE)
}

.validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) ||
      any(is.nan(domain))) {
    .ars_stop("domain must be a numeric vector of two non-NaN values")
  }
  if (domain[1L] >= domain[2L]) {
    .ars_stop("domain must have a strictly smaller lower endpoint")
  }
  invisible(domain)
}

.validate_sample_count <- function(n) {
  if ((!is.numeric(n) && !is.integer(n)) || length(n) != 1L ||
      is.na(n) || !is.finite(n) || n < 0 || n != floor(n) ||
      n > .Machine$integer.max) {
    .ars_stop("n must be one non-negative integer")
  }
  as.integer(n)
}

.as_density_function <- function(density_function, caller_environment) {
  if (is.function(density_function)) {
    return(density_function)
  }

  if (is.character(density_function)) {
    if (length(density_function) != 1L) {
      .ars_stop("a density expression supplied as character text must have length one")
    }
    density_function <- tryCatch(
      parse(text = density_function)[[1L]],
      error = function(e) .ars_stop("could not parse density expression")
    )
  } else if (is.expression(density_function)) {
    if (length(density_function) != 1L) {
      .ars_stop("density expression must contain exactly one expression")
    }
    density_function <- density_function[[1L]]
  }

  if (is.call(density_function) || is.name(density_function)) {
    expression_to_evaluate <- density_function
    return(function(x) {
      eval(expression_to_evaluate,
           envir = list(x = x), enclos = caller_environment)
    })
  }

  .ars_stop("density_function must be a function or an expression involving x")
}

.evaluate_density <- function(density_function, x) {
  value <- tryCatch(
    density_function(x),
    error = function(e) {
      .ars_stop(sprintf("density_function could not be evaluated: %s", e$message))
    }
  )

  if (!is.numeric(value) || is.complex(value) || length(value) != length(x)) {
    .ars_stop("density_function must be vectorized and return one numeric value per x")
  }
  if (anyNA(value) || any(!is.finite(value)) || any(value < 0)) {
    .ars_stop("density_function must return finite, non-negative values")
  }
  as.numeric(value)
}

.evaluate_log_density <- function(density_function, x) {
  log(.evaluate_density(density_function, x))
}

.initial_candidates <- function(domain) {
  lower <- domain[1L]
  upper <- domain[2L]
  fractions <- c(0.02, 0.05, 0.10, 0.20, 0.35, 0.50, 0.65, 0.80, 0.90, 0.95, 0.98)
  distances <- c(0.05, 0.10, 0.20, 0.35, 0.50, 0.75, 1, 2, 4, 8)

  if (is.finite(lower) && is.finite(upper)) {
    lower + (upper - lower) * fractions
  } else if (!is.finite(lower) && is.finite(upper)) {
    upper - rev(distances)
  } else if (is.finite(lower) && !is.finite(upper)) {
    lower + distances
  } else {
    sort(unique(c(-8, -4, -2, -1, -0.5, 0, 0.5, 1, 2, 4, 8,
                  seq(-20, 20, by = 1))))
  }
}

.fallback_candidates <- function(domain) {
  lower <- domain[1L]
  upper <- domain[2L]
  if (is.finite(lower) && is.finite(upper)) {
    lower + (upper - lower) * seq(0.001, 0.999, length.out = 201L)
  } else if (!is.finite(lower) && is.finite(upper)) {
    upper - 10^seq(-3, 3, length.out = 201L)
  } else if (is.finite(lower) && !is.finite(upper)) {
    lower + 10^seq(-3, 3, length.out = 201L)
  } else {
    sort(unique(c(seq(-100, 100, by = 0.5),
                  -10^seq(2, 4, length.out = 50L),
                  10^seq(2, 4, length.out = 50L))))
  }
}

.select_initial_points <- function(density_function, domain) {
  candidates <- sort(unique(.initial_candidates(domain)))
  candidates <- candidates[candidates > domain[1L] & candidates < domain[2L]]
  values <- .evaluate_log_density(density_function, candidates)
  positive <- is.finite(values)

  if (sum(positive) < 3L) {
    candidates <- sort(unique(.fallback_candidates(domain)))
    candidates <- candidates[candidates > domain[1L] & candidates < domain[2L]]
    values <- .evaluate_log_density(density_function, candidates)
    positive <- is.finite(values)
  }

  candidates <- candidates[positive]
  values <- values[positive]
  if (length(candidates) < 3L) {
    .ars_stop("could not find at least three interior points with positive density")
  }

  if (length(candidates) >  nine <- 9L) {
    indices <- unique(round(seq(1, length(candidates), length.out = nine)))
    candidates <- candidates[indices]
    values <- values[indices]
  }
  list(x = candidates, log_density = values)
}

.derivative_step <- function(x, domain) {
  scale <- max(1, abs(x))
  h <- 1e-5 * scale
  if (is.finite(domain[1L])) {
    h <- min(h, (x - domain[1L]) / 2)
  }
  if (is.finite(domain[2L])) {
    h <- min(h, (domain[2L] - x) / 2)
  }
  if (!is.finite(h) || h <= 10 * .Machine$double.eps * scale) {
    .ars_stop("cannot numerically differentiate the log density at an initial point")
  }
  h
}

.estimate_slopes <- function(density_function, x, domain) {
  slopes <- vapply(x, function(xi) {
    h <- .derivative_step(xi, domain)
    left <- xi - h
    right <- xi + h
    values <- .evaluate_log_density(density_function, c(left, right))
    if (any(!is.finite(values))) {
      .ars_stop("the density must be positive around every initial abscissa")
    }
    (values[2L] - values[1L]) / (2 * h)
  }, numeric(1L))

  if (any(!is.finite(slopes))) {
    .ars_stop("the log-density derivative could not be estimated")
  }
  slopes
}

.concavity_tolerance <- function(values) {
  1e-7 * pmax(1, abs(values))
}

.check_concavity_knots <- function(x, log_density, slopes) {
  if (length(x) < 2L) {
    return(invisible(TRUE))
  }
  secants <- diff(log_density) / diff(x)
  if (any(!is.finite(secants))) {
    .ars_stop("the log density must be finite between the initial abscissae")
  }

  slope_increase <- diff(slopes)
  if (any(slope_increase > .concavity_tolerance(slopes[-1L]))) {
    .ars_stop("density appears to be non-log-concave: estimated slopes increase")
  }

  secant_increase <- diff(secants)
  if (length(secant_increase) > 0L &&
      any(secant_increase > .concavity_tolerance(secants[-1L]))) {
    .ars_stop("density appears to be non-log-concave: secant slopes increase")
  }

  sandwich_tolerance <- 5e-5 * pmax(1, abs(secants), abs(slopes[-length(slopes)]),
                                     abs(slopes[-1L]))
  if (any(secants > slopes[-length(slopes)] + sandwich_tolerance) ||
      any(secants < slopes[-1L] - sandwich_tolerance)) {
    .ars_stop("density failed the log-concavity derivative check")
  }
  invisible(TRUE)
}

.concavity_check_grid <- function(density_function, domain, initial_points) {
  lower <- domain[1L]
  upper <- domain[2L]
  if (is.finite(lower) && is.finite(upper)) {
    span <- upper - lower
    points <- lower + span * seq(0.001, 0.999, length.out = 101L)
  } else if (!is.finite(lower) && is.finite(upper)) {
    points <- upper - c(0.01, 0.03, 0.1, 0.3, 0.7, 1, 2, 4, 8, 12)
  } else if (is.finite(lower) && !is.finite(upper)) {
    points <- lower + c(0.01, 0.03, 0.1, 0.3, 0.7, 1, 2, 4, 8, 12)
  } else {
    points <- c(seq(-12, 12, length.out = 121L),
                -16, -20, 16, 20)
  }
  points <- sort(unique(c(initial_points, points)))
  points <- points[points > lower & points < upper]
  log_values <- .evaluate_log_density(density_function, points)
  finite_values <- is.finite(log_values)
  if (sum(finite_values) < 3L) {
    .ars_stop("density has too few positive values to check log-concavity")
  }

  finite_points <- points[finite_values]
  finite_values <- log_values[finite_values]
  if (length(finite_points) >= 3L) {
    secants <- diff(finite_values) / diff(finite_points)
    if (any(diff(secants) > .concavity_tolerance(secants[-1L]))) {
      .ars_stop("density appears to be non-log-concave on the validation grid")
    }
  }
  invisible(TRUE)
}

.build_hull <- function(x, log_density, slopes, domain) {
  order_indices <- order(x)
  x <- x[order_indices]
  log_density <- log_density[order_indices]
  slopes <- slopes[order_indices]
  if (anyDuplicated(x)) {
    .ars_stop("adaptive abscissae must be distinct")
  }
  .check_concavity_knots(x, log_density, slopes)

  intercepts <- log_density - slopes * x
  keep <- integer(0L)
  breakpoints <- numeric(0L)
  slope_tolerance <- 1e-10 * pmax(1, abs(slopes))

  for (i in seq_along(x)) {
    if (length(keep) > 0L &&
        abs(slopes[i] - slopes[keep[length(keep)]]) <=
          max(slope_tolerance[i], slope_tolerance[keep[length(keep)]])) {
      previous <- keep[length(keep)]
      if (intercepts[i] < intercepts[previous]) {
        keep[length(keep)] <- i
      }
      next
    }

    repeat {
      if (length(keep) == 0L) {
        break
      }
      previous <- keep[length(keep)]
      crossing <- (intercepts[previous] - intercepts[i]) /
        (slopes[i] - slopes[previous])
      if (length(keep) == 1L || crossing > breakpoints[length(breakpoints)]) {
        break
      }
      keep <- keep[-length(keep)]
      if (length(breakpoints) > 0L) {
        breakpoints <- breakpoints[-length(breakpoints)]
      }
    }

    if (length(keep) > 0L) {
      previous <- keep[length(keep)]
      crossing <- (intercepts[previous] - intercepts[i]) /
        (slopes[i] - slopes[previous])
      breakpoints <- c(breakpoints, crossing)
    }
    keep <- c(keep, i)
  }

  hull_x <- x[keep]
  hull_slopes <- slopes[keep]
  hull_intercepts <- intercepts[keep]
  if (domain[1L] == -Inf && hull_slopes[1L] <= 0) {
    .ars_stop("left tail has no integrable tangent envelope; check the domain and density")
  }
  if (domain[2L] == Inf && hull_slopes[length(hull_slopes)] >= 0) {
    .ars_stop("right tail has no integrable tangent envelope; check the domain and density")
  }

  boundaries <- c(domain[1L], breakpoints, domain[2L])
  if (any(diff(boundaries) <= 0)) {
    .ars_stop("could not construct a valid tangent envelope; density may not be log-concave")
  }
  log_integrals <- vapply(seq_along(hull_slopes), function(i) {
    .log_linear_integral(hull_intercepts[i], hull_slopes[i],
                         boundaries[i], boundaries[i + 1L])
  }, numeric(1L))
  if (any(!is.finite(log_integrals))) {
    .ars_stop("tangent envelope is not integrable on the supplied domain")
  }

  list(x = hull_x, slopes = hull_slopes, intercepts = hull_intercepts,
       breakpoints = breakpoints, boundaries = boundaries,
       log_integrals = log_integrals)
}

.log_add_exp <- function(log_a, log_b) {
  if (is.infinite(log_a) && log_a < 0) return(log_b)
  if (is.infinite(log_b) && log_b < 0) return(log_a)
  max_value <- max(log_a, log_b)
  max_value + log(exp(log_a - max_value) + exp(log_b - max_value))
}

.log_linear_integral <- function(intercept, slope, lower, upper) {
  if (lower >= upper) {
    return(-Inf)
  }
  if (slope == 0) {
    if (!is.finite(lower) || !is.finite(upper)) return(-Inf)
    return(intercept + log(upper - lower))
  }
  if (!is.finite(lower)) {
    if (slope <= 0 || !is.finite(upper)) return(-Inf)
    return(intercept + slope * upper - log(slope))
  }
  if (!is.finite(upper)) {
    if (slope >= 0) return(-Inf)
    return(intercept + slope * lower - log(-slope))
  }

  left_value <- slope * lower
  right_value <- slope * upper
  maximum <- max(left_value, right_value)
  difference <- exp(left_value - maximum) - exp(right_value - maximum)
  if (difference == 0) {
    return(-Inf)
  }
  intercept + maximum + log(abs(difference)) - log(abs(slope))
}

.sample_linear_region <- function(intercept, slope, lower, upper) {
  uniform <- runif(1L)
  if (slope == 0) {
    return(lower + uniform * (upper - lower))
  }
  if (!is.finite(lower)) {
    return(upper + log(uniform) / slope)
  }
  if (!is.finite(upper)) {
    return(lower + log(uniform) / slope)
  }

  left_value <- slope * lower
  right_value <- slope * upper
  if (uniform <= 0) return(lower)
  if (uniform >= 1) return(upper)
  log_weight <- .log_add_exp(log1p(-uniform) + left_value,
                             log(uniform) + right_value)
  min(upper, max(lower, log_weight / slope))
}

.sample_from_hull <- function(hull) {
  maximum <- max(hull$log_integrals)
  probabilities <- exp(hull$log_integrals - maximum)
  region <- sample.int(length(probabilities), size = 1L, prob = probabilities)
  x <- .sample_linear_region(hull$intercepts[region], hull$slopes[region],
                             hull$boundaries[region], hull$boundaries[region + 1L])
  list(x = x, upper = hull$intercepts[region] + hull$slopes[region] * x)
}

.hull_value <- function(hull, x) {
  region <- findInterval(x, hull$breakpoints, left.open = FALSE) + 1L
  hull$intercepts[region] + hull$slopes[region] * x
}

.check_hull_grid <- function(hull, density_function, domain) {
  lower <- domain[1L]
  upper <- domain[2L]
  if (is.finite(lower) && is.finite(upper)) {
    span <- upper - lower
    points <- lower + span * seq(0.001, 0.999, length.out = 101L)
  } else if (!is.finite(lower) && is.finite(upper)) {
    points <- upper - c(0.01, 0.03, 0.1, 0.3, 0.7, 1, 2, 4, 8, 12)
  } else if (is.finite(lower) && !is.finite(upper)) {
    points <- lower + c(0.01, 0.03, 0.1, 0.3, 0.7, 1, 2, 4, 8, 12)
  } else {
    points <- c(seq(-12, 12, length.out = 121L), -16, -20, 16, 20)
  }
  points <- points[points > lower & points < upper]
  values <- .evaluate_log_density(density_function, points)
  upper_values <- .hull_value(hull, points)
  finite_values <- is.finite(values)
  if (any(values[finite_values] > upper_values[finite_values] +
          1e-6 * pmax(1, abs(values[finite_values]),
                       abs(upper_values[finite_values])))) {
    .ars_stop("density appears to be non-log-concave: tangent envelope was violated")
  }
  invisible(TRUE)
}

.add_adaptive_point <- function(density_function, x, points, log_density,
                                slopes, domain) {
  separation <- max(1, abs(x)) * 1e-10
  if (any(abs(points - x) <= separation)) {
    return(list(points = points, log_density = log_density, slopes = slopes))
  }
  new_log_density <- .evaluate_log_density(density_function, x)
  if (!is.finite(new_log_density)) {
    return(list(points = points, log_density = log_density, slopes = slopes))
  }
  new_slope <- .estimate_slopes(density_function, x, domain)
  points <- c(points, x)
  log_density <- c(log_density, new_log_density)
  slopes <- c(slopes, new_slope)
  order_indices <- order(points)
  points <- points[order_indices]
  log_density <- log_density[order_indices]
  slopes <- slopes[order_indices]
  .check_concavity_knots(points, log_density, slopes)
  list(points = points, log_density = log_density, slopes = slopes)
}

#' Adaptive rejection sampler for a one-dimensional log-concave density.
#'
#' density_function may be a function, a call such as dnorm(x), or a
#' one-expression expression object.  The function must accept a numeric
#' vector and return non-negative density values of the same length.
ars <- function(density_function, domain, n = sample_count) {
  domain <- .validate_domain(domain)
  n <- .validate_sample_count(n)
  density_function <- .as_density_function(density_function, parent.frame())

  # Evaluate a vector before doing any sampling so non-vectorized inputs fail
  # with a useful message.
  probe <- if (is.finite(domain[1L]) && is.finite(domain[2L])) {
    domain[1L] + (domain[2L] - domain[1L]) * c(0.25, 0.5, 0.75)
  } else if (is.finite(domain[1L])) {
    domain[1L] + c(0.25, 0.5, 1)
  } else if (is.finite(domain[2L])) {
    domain[2L] - c(0.25, 0.5, 1)
  } else {
    c(-1, 0, 1)
  }
  .evaluate_density(density_function, probe)

  initial <- .select_initial_points(density_function, domain)
  slopes <- .estimate_slopes(density_function, initial$x, domain)
  .check_concavity_knots(initial$x, initial$log_density, slopes)
  .concavity_check_grid(density_function, domain, initial$x)
  hull <- .build_hull(initial$x, initial$log_density, slopes, domain)
  .check_hull_grid(hull, density_function, domain)

  if (n == 0L) {
    return(numeric(0L))
  }

  samples <- numeric(n)
  accepted <- 0L
  iterations <- 0L
  max_iterations <- max(10000, min(1000000, 100 * n + 1000))

  while (accepted < n) {
    iterations <- iterations + 1L
    if (iterations > max_iterations) {
      .ars_stop("ARS exceeded its rejection limit; check log-concavity and the domain")
    }

    proposal <- .sample_from_hull(hull)
    x <- proposal$x
    upper_value <- proposal$upper
    log_value <- .evaluate_log_density(density_function, x)
    if (is.finite(log_value)) {
      tolerance <- 1e-6 * max(1, abs(log_value), abs(upper_value))
      if (log_value > upper_value + tolerance) {
        .ars_stop("density appears to be non-log-concave: sampled point exceeds tangent envelope")
      }
      if (log(runif(1L)) <= log_value - upper_value) {
        accepted <- accepted + 1L
        samples[accepted] <- x
        next
      }
    }

    if (is.finite(log_value)) {
      updated <- .add_adaptive_point(density_function, x, initial$x,
                                     initial$log_density, slopes, domain)
      initial$x <- updated$points
      initial$log_density <- updated$log_density
      slopes <- updated$slopes
      hull <- .build_hull(initial$x, initial$log_density, slopes, domain)
      .check_hull_grid(hull, density_function, domain)
    }
  }
  samples
}

.format_statistic <- function(value) {
  if (!is.finite(value)) "NA" else sprintf("%.5f", value)
}

.run_test <- function(name, expression, mean_value = NA_real_, sd_value = NA_real_) {
  passed <- tryCatch(isTRUE(force(expression)), error = function(e) FALSE)
  status <- if (passed) "PASS" else "FAIL"
  cat(sprintf("%s: %s (mean=%s, sd=%s)\n", name, status,
              .format_statistic(mean_value), .format_statistic(sd_value)))
  passed
}

# Formal stochastic tests against known moments.  The normal sample is also
# written to the required sample artifact path.
test <- function(seed = 20240229L, sample_size = 5000L) {
  if (!is.numeric(seed) || length(seed) != 1L || !is.finite(seed)) {
    .ars_stop("seed must be one finite number")
  }
  sample_size <- .validate_sample_count(sample_size)
  set.seed(as.integer(seed))
  all_passed <- TRUE

  normal <- tryCatch(ars(dnorm, c(-Inf, Inf), n = sample_size),
                     error = function(e) e)
  if (inherits(normal, "error")) {
    cat(sprintf("NORMAL_MOMENTS: FAIL (mean=NA, sd=NA; %s)\n", normal$message))
    all_passed <- FALSE
  } else {
    normal_mean <- mean(normal)
    normal_sd <- sd(normal)
    write.table(normal, file = "/app/normal_samples.txt", row.names = FALSE,
                col.names = FALSE, quote = FALSE)
    all_passed <- .run_test(
      "NORMAL_MOMENTS",
      abs(normal_mean) < 0.10 && abs(normal_sd - 1) < 0.10,
      normal_mean, normal_sd
    ) && all_passed
  }

  exponential <- tryCatch(
    ars(function(x) dexp(x, rate = 1), c(0, Inf), n = sample_size),
    error = function(e) e
  )
  if (inherits(exponential, "error")) {
    cat(sprintf("EXPONENTIAL_MOMENTS: FAIL (mean=NA, sd=NA; %s)\n", exponential$message))
    all_passed <- FALSE
  } else {
    exponential_mean <- mean(exponential)
    exponential_sd <- sd(exponential)
    all_passed <- .run_test(
      "EXPONENTIAL_MOMENTS",
      abs(exponential_mean - 1) < 0.10 && abs(exponential_sd - 1) < 0.10,
      exponential_mean, exponential_sd
    ) && all_passed
  }

  validation_passed <- TRUE
  validation_passed <- tryCatch({
    ars(dnorm, c(1, 0), n = 1L)
    FALSE
  }, error = function(e) TRUE) && validation_passed
  validation_passed <- tryCatch({
    ars(dnorm, c(-Inf, Inf), n = -1L)
    FALSE
  }, error = function(e) TRUE) && validation_passed
  all_passed <- .run_test("INPUT_VALIDATION", validation_passed) && all_passed

  nonconcave_passed <- tryCatch({
    ars(function(x) exp(-0.5 * x^2) * (1 + 0.8 * sin(3 * x)),
        c(-4, 4), n = 5L)
    FALSE
  }, error = function(e) grepl("non-log-concave|log-concavity|envelope",
                                e$message, ignore.case = TRUE))
  all_passed <- .run_test("NON_LOG_CONCAVITY_CHECK", nonconcave_passed) && all_passed

  invisible(all_passed)
}

