+#' Adaptive rejection sampler for a one-dimensional log-concave density.
+#'
+#' density_function may be a function, a call such as dnorm(x), or a
+#' one-expression expression object.  The function must accept a numeric
+#' vector and return non-negative density values of the same length.
+ars <- function(density_function, domain, n = sample_count) {
+  domain <- .validate_domain(domain)
+  n <- .validate_sample_count(n)
+  density_function <- .as_density_function(density_function, parent.frame())
+
+  # Evaluate a vector before doing any sampling so non-vectorized inputs fail
+  # with a useful message.
+  probe <- if (is.finite(domain[1L]) && is.finite(domain[2L])) {
+    domain[1L] + (domain[2L] - domain[1L]) * c(0.25, 0.5, 0.75)
+  } else if (is.finite(domain[1L])) {
+    domain[1L] + c(0.25, 0.5, 1)
+  } else if (is.finite(domain[2L])) {
+    domain[2L] - c(0.25, 0.5, 1)
+  } else {
+    c(-1, 0, 1)
+  }
+  .evaluate_density(density_function, probe)
+
+  initial <- .select_initial_points(density_function, domain)
+  slopes <- .estimate_slopes(density_function, initial$x, domain)
+  .check_concavity_knots(initial$x, initial$log_density, slopes)
+  .concavity_check_grid(density_function, domain, initial$x)
+  hull <- .build_hull(initial$x, initial$log_density, slopes, domain)
+  .check_hull_grid(hull, density_function, domain)
+
+  if (n == 0L) {
+    return(numeric(0L))
+  }
+
+  samples <- numeric(n)
+  accepted <- 0L
+  iterations <- 0L
+  max_iterations <- max(10000, min(1000000, 100 * n + 1000))
+
+  while (accepted < n) {
+    iterations <- iterations + 1L
+    if (iterations > max_iterations) {
+      .ars_stop("ARS exceeded its rejection limit; check log-concavity and the domain")
+    }
+
+    proposal <- .sample_from_hull(hull)
+    x <- proposal$x
+    upper_value <- proposal$upper
+    log_value <- .evaluate_log_density(density_function, x)
+    if (is.finite(log_value)) {
+      tolerance <- 1e-6 * max(1, abs(log_value), abs(upper_value))
+      if (log_value > upper_value + tolerance) {
+        .ars_stop("density appears to be non-log-concave: sampled point exceeds tangent envelope")
+      }
+      if (log(runif(1L)) <= log_value - upper_value) {
+        accepted <- accepted + 1L
+        samples[accepted] <- x
+        next
+      }
+    }
+
+    if (is.finite(log_value)) {
+      updated <- .add_adaptive_point(density_function, x, initial$x,
+                                     initial$log_density, slopes, domain)
+      initial$x <- updated$points
+      initial$log_density <- updated$log_density
+      slopes <- updated$slopes
+      hull <- .build_hull(initial$x, initial$log_density, slopes, domain)
+      .check_hull_grid(hull, density_function, domain)
+    }
+  }
+  samples
+}
+
