+.run_test <- function(name, expression, mean_value = NA_real_, sd_value = NA_real_) {
+  passed <- tryCatch(isTRUE(force(expression)), error = function(e) FALSE)
+  status <- if (passed) "PASS" else "FAIL"
+  cat(sprintf("%s: %s (mean=%s, sd=%s)\n", name, status,
+              .format_statistic(mean_value), .format_statistic(sd_value)))
+  passed
+}
