+# Formal stochastic tests against known moments.  The normal sample is also
+# written to the required sample artifact path.
+test <- function(seed = 20240229L, sample_size = 5000L) {
+  if (!is.numeric(seed) || length(seed) != 1L || !is.finite(seed)) {
+    .ars_stop("seed must be one finite number")
+  }
+  sample_size <- .validate_sample_count(sample_size)
+  set.seed(as.integer(seed))
+  all_passed <- TRUE
+
+  normal <- tryCatch(ars(dnorm, c(-Inf, Inf), n = sample_size),
+                     error = function(e) e)
+  if (inherits(normal, "error")) {
+    cat(sprintf("NORMAL_MOMENTS: FAIL (mean=NA, sd=NA; %s)\n", normal$message))
+    all_passed <- FALSE
+  } else {
+    normal_mean <- mean(normal)
+    normal_sd <- sd(normal)
+    write.table(normal, file = "/app/normal_samples.txt", row.names = FALSE,
+                col.names = FALSE, quote = FALSE)
+    all_passed <- .run_test(
+      "NORMAL_MOMENTS",
+      abs(normal_mean) < 0.10 && abs(normal_sd - 1) < 0.10,
+      normal_mean, normal_sd
+    ) && all_passed
+  }
+
+  exponential <- tryCatch(
+    ars(function(x) dexp(x, rate = 1), c(0, Inf), n = sample_size),
+    error = function(e) e
+  )
+  if (inherits(exponential, "error")) {
+    cat(sprintf("EXPONENTIAL_MOMENTS: FAIL (mean=NA, sd=NA; %s)\n", exponential$message))
+    all_passed <- FALSE
+  } else {
+    exponential_mean <- mean(exponential)
+    exponential_sd <- sd(exponential)
+    all_passed <- .run_test(
+      "EXPONENTIAL_MOMENTS",
+      abs(exponential_mean - 1) < 0.10 && abs(exponential_sd - 1) < 0.10,
+      exponential_mean, exponential_sd
+    ) && all_passed
+  }
+
+  validation_passed <- TRUE
+  validation_passed <- tryCatch({
+    ars(dnorm, c(1, 0), n = 1L)
+    FALSE
+  }, error = function(e) TRUE) && validation_passed
+  validation_passed <- tryCatch({
+    ars(dnorm, c(-Inf, Inf), n = -1L)
+    FALSE
+  }, error = function(e) TRUE) && validation_passed
+  all_passed <- .run_test("INPUT_VALIDATION", validation_passed) && all_passed
+
+  nonconcave_passed <- tryCatch({
+    ars(function(x) exp(-0.5 * x^2) * (1 + 0.8 * sin(3 * x)),
+        c(-4, 4), n = 5L)
+    FALSE
+  }, error = function(e) grepl("non-log-concave|log-concavity|envelope",
+                                e$message, ignore.case = TRUE))
+  all_passed <- .run_test("NON_LOG_CONCAVITY_CHECK", nonconcave_passed) && all_passed
+
+  invisible(all_passed)
+}

