    if (!is.finite(value)) 
        "NA"
    else sprintf("%.5f", value)
}, .run_test <- function(name, expression, mean_value = NA_real_, 
    sd_value = NA_real_) {
    passed <- tryCatch(isTRUE(force(expression)), error = function(e) FALSE)
    status <- if (passed) 
        "PASS"
    else "FAIL"
    cat(sprintf("%s: %s (mean=%s, sd=%s)\n", name, status, .format_statistic(mean_value), 
        .format_statistic(sd_value)))
    passed
}, test <- function(seed = 20240229L, sample_size = 5000L) {
    if (!is.numeric(seed) || length(seed) != 1L || !is.finite(seed)) {
        .ars_stop("seed must be one finite number")
    }
    sample_size <- .validate_sample_count(sample_size)
    set.seed(as.integer(seed))
    all_passed <- TRUE
    normal <- tryCatch(ars(dnorm, c(-Inf, Inf), n = sample_size), 
        error = function(e) e)
    if (inherits(normal, "error")) {
        cat(sprintf("NORMAL_MOMENTS: FAIL (mean=NA, sd=NA; %s)\n", 
            normal$message))
        all_passed <- FALSE
    }
    else {
        normal_mean <- mean(normal)
        normal_sd <- sd(normal)
        write.table(normal, file = "/app/normal_samples.txt", 
            row.names = FALSE, col.names = FALSE, quote = FALSE)
        all_passed <- .run_test("NORMAL_MOMENTS", abs(normal_mean) < 
            0.1 && abs(normal_sd - 1) < 0.1, normal_mean, normal_sd) && 
            all_passed
    }
    exponential <- tryCatch(ars(function(x) dexp(x, rate = 1), 
        c(0, Inf), n = sample_size), error = function(e) e)
    if (inherits(exponential, "error")) {
        cat(sprintf("EXPONENTIAL_MOMENTS: FAIL (mean=NA, sd=NA; %s)\n", 
            exponential$message))
        all_passed <- FALSE
    }
    else {
        exponential_mean <- mean(exponential)
        exponential_sd <- sd(exponential)
        all_passed <- .run_test("EXPONENTIAL_MOMENTS", abs(exponential_mean - 
            1) < 0.1 && abs(exponential_sd - 1) < 0.1, exponential_mean, 
            exponential_sd) && all_passed
    }
    validation_passed <- TRUE
    validation_passed <- tryCatch({
        ars(dnorm, c(1, 0), n = 1L)
        FALSE
    }, error = function(e) TRUE) && validation_passed
    validation_passed <- tryCatch({
        ars(dnorm, c(-Inf, Inf), n = -1L)
        FALSE
    }, error = function(e) TRUE) && validation_passed
    all_passed <- .run_test("INPUT_VALIDATION", validation_passed) && 
        all_passed
    nonconcave_passed <- tryCatch({
        ars(function(x) exp(-0.5 * x^2) * (1 + 0.8 * sin(3 * 
            x)), c(-4, 4), n = 5L)
        FALSE
    }, error = function(e) grepl("non-log-concave|log-concavity|envelope", 
        e$message, ignore.case = TRUE))
    all_passed <- .run_test("NON_LOG_CONCAVITY_CHECK", nonconcave_passed) && 
        all_passed
    invisible(all_passed)
})
